-- Schema of tags, taggings, media_parts, media_items, metadata_items from lab Plex Media Server 1.43.4.10903
-- (".schema" read-only). Removed: fts4_*_icu triggers and index_title_sort_icu, which need Plex's ICU build.
CREATE TABLE "tags" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, "metadata_item_id" integer, "tag" varchar(255) COLLATE NOCASE, "tag_type" integer, "user_thumb_url" varchar(255), "user_art_url" varchar(255), "user_music_url" varchar(255), "created_at" dt_integer(8), "updated_at" dt_integer(8), "tag_value" integer, "extra_data" varchar(255), 'key' varchar(255), 'parent_id' integer);
CREATE INDEX "index_tags_on_tag" ON "tags" ("tag" );
CREATE INDEX "index_tags_on_tag_type" ON "tags" ("tag_type" );
CREATE INDEX "index_tags_on_tag_type_and_tag" ON "tags" ("tag_type", "tag" );
CREATE INDEX 'index_tags_on_key' ON 'tags' ('key');
CREATE INDEX 'index_tags_on_parent_id' ON 'tags' ('parent_id');
CREATE TABLE "taggings" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, "metadata_item_id" integer, "tag_id" integer, "index" integer, "text" varchar(255), "time_offset" integer, "end_time_offset" integer, "thumb_url" varchar(255), "created_at" dt_integer(8), "extra_data" varchar(255));
CREATE INDEX "index_taggings_on_metadata_item_id" ON "taggings" ("metadata_item_id" );
CREATE INDEX "index_taggings_on_tag_id" ON "taggings" ("tag_id" );
CREATE TABLE "media_parts" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, "media_item_id" integer, "directory_id" integer, "hash" varchar(255), "open_subtitle_hash" varchar(255), "file" varchar(255), "index" integer, "size" integer(8), "duration" integer, "created_at" dt_integer(8), "updated_at" dt_integer(8), "deleted_at" dt_integer(8), "extra_data" varchar(255));
CREATE INDEX "index_media_parts_on_directory_id" ON "media_parts" ("directory_id" );
CREATE INDEX "index_media_parts_on_media_item_id" ON "media_parts" ("media_item_id" );
CREATE INDEX "index_media_parts_on_hash" ON "media_parts" ("hash" );
CREATE INDEX "index_media_parts_on_file" ON "media_parts" ("file" );
CREATE INDEX "index_media_parts_on_deleted_at" ON "media_parts" ("deleted_at" );
CREATE INDEX "index_media_parts_on_size" ON "media_parts" ("size" );
CREATE TABLE "media_items" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, "library_section_id" integer, "section_location_id" integer, "metadata_item_id" integer, "type_id" integer, "width" integer, "height" integer, "size" integer(8), "duration" integer, "bitrate" integer, "container" varchar(255), "video_codec" varchar(255), "audio_codec" varchar(255), "display_aspect_ratio" float, "frames_per_second" float, "audio_channels" integer, "interlaced" boolean, "source" varchar(255), "hints" varchar(255), "display_offset" integer, "settings" varchar(255), "created_at" dt_integer(8), "updated_at" dt_integer(8), "optimized_for_streaming" boolean, "deleted_at" dt_integer(8), "media_analysis_version" integer DEFAULT 0, "sample_aspect_ratio" float, "extra_data" varchar(255), "proxy_type" integer, 'channel_id' integer, 'begins_at' dt_integer(8), 'ends_at' dt_integer(8), 'color_trc' varchar(255));
CREATE INDEX "index_media_items_on_library_section_id" ON "media_items" ("library_section_id" );
CREATE INDEX "index_media_items_on_metadata_item_id" ON "media_items" ("metadata_item_id" );
CREATE INDEX "index_media_items_on_deleted_at" ON "media_items" ("deleted_at" );
CREATE INDEX "index_media_items_on_media_analysis_version" ON "media_items" ("media_analysis_version" );
CREATE INDEX 'index_media_items_on_begins_at' ON 'media_items' ('begins_at');
CREATE INDEX 'index_media_items_on_ends_at' ON 'media_items' ('ends_at');
CREATE INDEX 'index_media_items_on_channel_id' ON 'media_items' ('channel_id');
CREATE INDEX 'index_media_items_on_channel_id_and_begins_at' ON 'media_items' ('channel_id','begins_at');
CREATE TABLE "metadata_items" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, "library_section_id" integer, "parent_id" integer, "metadata_type" integer, "guid" varchar(255), "media_item_count" integer, "title" varchar(255), "title_sort" varchar(255) COLLATE NOCASE, "original_title" varchar(255), "studio" varchar(255), "rating" float, "rating_count" integer, "tagline" varchar(255), "summary" text, "trivia" text, "quotes" text, "content_rating" varchar(255), "content_rating_age" integer, "index" integer, "absolute_index" integer, "duration" integer, "user_thumb_url" varchar(255), "user_art_url" varchar(255), "user_banner_url" varchar(255), "user_music_url" varchar(255), "user_fields" varchar(255), "tags_genre" varchar(255), "tags_collection" varchar(255), "tags_director" varchar(255), "tags_writer" varchar(255), "tags_star" varchar(255), "originally_available_at" dt_integer(8), "available_at" dt_integer(8), "expires_at" dt_integer(8), "refreshed_at" dt_integer(8), "year" integer, "added_at" dt_integer(8), "created_at" dt_integer(8), "updated_at" dt_integer(8), "deleted_at" dt_integer(8), "tags_country" varchar(255), "extra_data" varchar(255), "hash" varchar(255), "audience_rating" float, "changed_at" integer(8) DEFAULT 0, "resources_changed_at" integer(8) DEFAULT 0, 'remote' integer, 'edition_title' varchar(255), 'slug' varchar(255), 'user_clear_logo_url' varchar(255), 'is_adult' integer, 'metadata_agent_provider_group_id' integer, 'user_square_art_url' varchar(255));
CREATE INDEX "index_metadata_items_on_library_section_id" ON "metadata_items" ("library_section_id" );
CREATE INDEX "index_metadata_items_on_parent_id" ON "metadata_items" ("parent_id" );
CREATE INDEX "index_metadata_items_on_created_at" ON "metadata_items" ("created_at" );
CREATE INDEX "index_metadata_items_on_index" ON "metadata_items" ("index" );
CREATE INDEX "index_metadata_items_on_title" ON "metadata_items" ("title" );
CREATE INDEX "index_metadata_items_on_title_sort" ON "metadata_items" ("title_sort" );
CREATE INDEX "index_metadata_items_on_guid" ON "metadata_items" ("guid" );
CREATE INDEX "index_metadata_items_on_metadata_type" ON "metadata_items" ("metadata_type" );
CREATE INDEX "index_metadata_items_on_deleted_at" ON "metadata_items" ("deleted_at" );
CREATE INDEX "index_metadata_items_on_library_section_id_and_metadata_type_and_added_at" ON "metadata_items" ("library_section_id", "metadata_type", "added_at" );
CREATE INDEX "index_metadata_items_on_hash" ON "metadata_items" ("hash" );
CREATE INDEX "index_metadata_items_on_added_at" ON "metadata_items" ("added_at" );
CREATE INDEX "index_metadata_items_on_originally_available_at" ON "metadata_items" ("originally_available_at" );
CREATE INDEX "index_metadata_items_on_changed_at" ON "metadata_items" ("changed_at" );
CREATE INDEX "index_metadata_items_on_resources_changed_at" ON "metadata_items" ("resources_changed_at" );
CREATE INDEX 'index_metadata_items_on_original_title' ON 'metadata_items' ('original_title');
CREATE INDEX 'index_metadata_items_on_absolute_index' ON 'metadata_items' ('absolute_index');
CREATE INDEX 'index_metadata_items_on_remote' ON 'metadata_items' ('remote');
CREATE INDEX 'index_metadata_items_on_edition_title' ON 'metadata_items' ('edition_title');
CREATE INDEX 'index_metadata_items_on_slug' ON 'metadata_items' ('slug');
CREATE INDEX 'index_metadata_items_on_is_adult' ON 'metadata_items' ('is_adult');
CREATE INDEX 'index_metadata_items_on_metadata_agent_provider_group_id' ON 'metadata_items' ('metadata_agent_provider_group_id');
